create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.content_items(id uuid primary key default gen_random_uuid(),category text not null check(category in ('gallery','room','service','offer')),title text not null,description text,image_path text not null,image_url text not null,price_label text,sort_order integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.booking_requests(id uuid primary key default gen_random_uuid(),service text not null,guest_count text,desired_date date,desired_time time,customer_name text not null,phone text not null,comment text,status text not null default 'new' check(status in ('new','confirmed','completed','cancelled')),created_at timestamptz not null default now());
alter table public.admin_users enable row level security;
alter table public.content_items enable row level security;
alter table public.booking_requests enable row level security;
drop policy if exists "Admins can read own admin row" on public.admin_users;
create policy "Admins can read own admin row" on public.admin_users for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists "Public can read active content" on public.content_items;
create policy "Public can read active content" on public.content_items for select to anon,authenticated using(is_active=true);
drop policy if exists "Admins manage content" on public.content_items;
create policy "Admins manage content" on public.content_items for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Visitors can submit booking requests" on public.booking_requests;
create policy "Visitors can submit booking requests" on public.booking_requests for insert to anon,authenticated with check(length(trim(customer_name)) between 2 and 100 and length(trim(phone)) between 5 and 40 and length(trim(service)) between 2 and 100);
drop policy if exists "Admins read booking requests" on public.booking_requests;
create policy "Admins read booking requests" on public.booking_requests for select to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins update booking requests" on public.booking_requests;
create policy "Admins update booking requests" on public.booking_requests for update to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
grant select on public.content_items to anon,authenticated;
grant insert on public.booking_requests to anon,authenticated;
grant select,insert,update,delete on public.content_items to authenticated;
grant select,update on public.booking_requests to authenticated;
grant select on public.admin_users to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('kovsh-media','kovsh-media',true,8388608,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=8388608,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "Public can view kovsh media" on storage.objects;
create policy "Public can view kovsh media" on storage.objects for select to anon,authenticated using(bucket_id='kovsh-media');
drop policy if exists "Admins upload kovsh media" on storage.objects;
create policy "Admins upload kovsh media" on storage.objects for insert to authenticated with check(bucket_id='kovsh-media' and exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins update kovsh media" on storage.objects;
create policy "Admins update kovsh media" on storage.objects for update to authenticated using(bucket_id='kovsh-media' and exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(bucket_id='kovsh-media' and exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins delete kovsh media" on storage.objects;
create policy "Admins delete kovsh media" on storage.objects for delete to authenticated using(bucket_id='kovsh-media' and exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
